import (
	context "context"
	fernclient "github.com/go-optional-request-body/fern/client"
)

client := fernclient.NewClient()
response, err := client.WaterAllPlants(
	context.TODO(),
	nil,
)

import (
	context "context"
	fern "github.com/go-optional-request-body/fern"
	fernclient "github.com/go-optional-request-body/fern/client"
)

client := fernclient.NewClient()
response, err := client.MistPlant(
	context.TODO(),
	&fern.MistPlantRequest{
		PlantID: "plant-id",
	},
)

import (
	context "context"
	fern "github.com/go-optional-request-body/fern"
	fernclient "github.com/go-optional-request-body/fern/client"
)

client := fernclient.NewClient()
response, err := client.PrunePlant(
	context.TODO(),
	&fern.PrunePlantRequest{
		PlantID: "plant-id",
		Body: &fern.WateringRequest{
			Milliliters: fern.Float64(
				60,
			),
		},
	},
)

